insert into organizations (id, name) values ('00000000-0000-4000-8000-00000000c0de', 'Casa do Mar') on conflict do nothing;
insert into restaurants (id, organization_id, slug, name, tagline, description, cuisine, address, city, phone, locale, currency, timezone, brand, settings, plan, is_published)
values
  ('00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-00000000c0de', 'casa-do-mar', 'Casa do Mar', 'Cozinha de mar e brasa · Cascais', 'Peixe da lota de Cascais, marisco vivo e brasa de carvão de azinho. Uma casa de família desde 1987, a dois passos da Praia da Ribeira.', 'Portuguesa · Peixe e marisco', 'Rua Frederico Arouca 42, 2750-355 Cascais', 'Cascais', '+351 214 000 000', 'pt-PT', 'EUR', 'Europe/Lisbon', '{"accent":"#1f4e5a","coverUrl":"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1200&q=75"}'::jsonb, '{"orderingEnabled":true,"serviceNote":"Couvert servido apenas a pedido. IVA incluído à taxa legal em vigor.","googleReviewUrl":"https://g.page/r/casa-do-mar-demo/review"}'::jsonb, 'demo', true)
insert into restaurant_counters (restaurant_id) values ('00000000-0000-4000-8000-00000000c0de') on conflict do nothing;
insert into menu_categories (id, restaurant_id, name, description, position, is_visible) values
  ('00000000-0000-4000-8000-0000000ca701', '00000000-0000-4000-8000-00000000c0de', 'Para começar', 'Petiscos para partilhar enquanto se escolhe.', 1, true),
  ('00000000-0000-4000-8000-0000000ca702', '00000000-0000-4000-8000-00000000c0de', 'Do mar', 'Peixe do dia e marisco, na brasa ou no tacho.', 2, true),
  ('00000000-0000-4000-8000-0000000ca703', '00000000-0000-4000-8000-00000000c0de', 'Da terra', 'Carnes maturadas e porco preto alentejano.', 3, true),
  ('00000000-0000-4000-8000-0000000ca704', '00000000-0000-4000-8000-00000000c0de', 'Da horta', 'Pratos vegetarianos, sem compromisso no sabor.', 4, true),
  ('00000000-0000-4000-8000-0000000ca705', '00000000-0000-4000-8000-00000000c0de', 'Sobremesas', 'Doçaria conventual e clássicos da casa.', 5, true),
  ('00000000-0000-4000-8000-0000000ca706', '00000000-0000-4000-8000-00000000c0de', 'Garrafeira & bebidas', 'Vinhos portugueses a copo e à garrafa.', 6, true)
insert into dishes (id, restaurant_id, category_id, name, description, price_cents, image_url, allergens, ingredients, tags, options, pairing, prep_minutes, is_available, is_featured, position) values
  ('00000000-0000-4000-8000-0000000d1001', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca701', 'Pão da casa e manteiga de algas', 'Pão de massa-mãe de fermentação lenta, manteiga dos Açores com alga nori e flor de sal.', 350, 'https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&w=1200&q=75', array['gluten', 'milk']::text[], array['pão de massa-mãe', 'manteiga dos Açores', 'alga nori', 'flor de sal']::text[], array['vegetarian', 'to_share']::text[], '[]'::jsonb, null, 3, true, false, 1),
  ('00000000-0000-4000-8000-0000000d1002', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca701', 'Amêijoas à Bulhão Pato', 'Amêijoa-boa da Ria Formosa, alho, coentros, azeite e um toque de limão. Pão para molhar.', 1650, 'https://images.unsplash.com/photo-1625943553852-781c6dd46faa?auto=format&fit=crop&w=1200&q=75', array['molluscs', 'gluten']::text[], array['amêijoa-boa', 'alho', 'coentros', 'azeite', 'limão', 'vinho branco']::text[], array['signature', 'popular', 'to_share']::text[], '[]'::jsonb, 'Vinho Verde Alvarinho', 10, true, true, 2),
  ('00000000-0000-4000-8000-0000000d1003', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca701', 'Pastéis de bacalhau', 'Quatro unidades, fritos na hora. Bacalhau desfiado, batata e salsa, com maionese de limão.', 750, 'https://images.unsplash.com/photo-1606755962773-d324e0a13086?auto=format&fit=crop&w=1200&q=75', array['fish', 'eggs', 'gluten']::text[], array['bacalhau', 'batata', 'ovo', 'salsa', 'cebola', 'limão']::text[], array['popular', 'to_share']::text[], '[]'::jsonb, 'Vinho Verde ou cerveja', 8, true, false, 3),
  ('00000000-0000-4000-8000-0000000d1004', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca701', 'Camarão ao alho', 'Camarão de Moçambique salteado em azeite, alho laminado, malagueta e cerveja.', 1450, 'https://images.unsplash.com/photo-1565680018434-b513d5e5fd47?auto=format&fit=crop&w=1200&q=75', array['crustaceans', 'gluten']::text[], array['camarão', 'alho', 'malagueta', 'azeite', 'cerveja', 'coentros']::text[], array['spicy', 'to_share']::text[], '[]'::jsonb, 'Alvarinho ou rosé', 9, true, false, 4),
  ('00000000-0000-4000-8000-0000000d1005', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca701', 'Peixinhos da horta', 'Feijão-verde em polme leve e estaladiço, maionese de ervas.', 800, 'https://images.unsplash.com/photo-1541014741259-de529411b96a?auto=format&fit=crop&w=1200&q=75', array['gluten', 'eggs']::text[], array['feijão-verde', 'farinha de trigo', 'ovo', 'ervas aromáticas']::text[], array['vegetarian', 'to_share']::text[], '[]'::jsonb, null, 8, true, false, 5),
  ('00000000-0000-4000-8000-0000000d1006', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca702', 'Polvo à lagareiro', 'Polvo cozido lentamente e acabado na brasa, batata a murro, grelos salteados e azeite virgem extra com alho.', 2450, 'https://images.unsplash.com/photo-1599487488170-d11ec9c172f0?auto=format&fit=crop&w=1200&q=75', array['molluscs']::text[], array['polvo', 'batata-nova', 'grelos', 'alho', 'azeite virgem extra', 'louro']::text[], array['signature', 'popular', 'gluten_free']::text[], '[]'::jsonb, 'Alvarinho ou um branco do Douro com alguma estrutura', 20, true, true, 6),
  ('00000000-0000-4000-8000-0000000d1007', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca702', 'Arroz de marisco', 'Para duas pessoas. Arroz carolino malandrinho com lagosta, camarão, amêijoa e mexilhão, no tacho.', 5200, 'https://images.unsplash.com/photo-1534080564583-6be75777b70a?auto=format&fit=crop&w=1200&q=75', array['crustaceans', 'molluscs', 'celery']::text[], array['arroz carolino', 'lagosta', 'camarão', 'amêijoa', 'mexilhão', 'tomate', 'coentros']::text[], array['signature', 'to_share']::text[], '[]'::jsonb, 'Alvarinho ou espumante da Bairrada', 30, true, true, 7),
  ('00000000-0000-4000-8000-0000000d1008', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca702', 'Bacalhau à Brás', 'Bacalhau desfiado, batata palha fina, ovo cremoso, azeitonas pretas e salsa.', 1750, 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=1200&q=75', array['fish', 'eggs']::text[], array['bacalhau', 'batata palha', 'ovo', 'cebola', 'azeitona preta', 'salsa']::text[], array['popular']::text[], '[]'::jsonb, 'Branco do Dão ou Vinho Verde', 15, true, false, 8),
  ('00000000-0000-4000-8000-0000000d1009', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca702', 'Dourada escalada na brasa', 'Dourada inteira de mar, escalada e grelhada em carvão de azinho, legumes salteados e batata cozida.', 1950, 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?auto=format&fit=crop&w=1200&q=75', array['fish']::text[], array['dourada', 'batata', 'legumes da época', 'azeite', 'limão']::text[], array['light', 'gluten_free']::text[], '[{"id":"extra","name":"Acompanhamento extra","min":0,"max":2,"choices":[{"id":"batata-frita","name":"Batata frita da casa","priceDeltaCents":350},{"id":"salada","name":"Salada mista","priceDeltaCents":300},{"id":"arroz","name":"Arroz de tomate","priceDeltaCents":400}]}]'::jsonb, 'Vinho Verde Loureiro', 18, true, false, 9),
  ('00000000-0000-4000-8000-0000000d1010', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca702', 'Lulas grelhadas', 'Lulas da costa grelhadas inteiras, molho de manteiga e limão, arroz de coentros.', 1800, 'https://images.unsplash.com/photo-1604909052743-94e838986d24?auto=format&fit=crop&w=1200&q=75', array['molluscs', 'milk']::text[], array['lulas', 'manteiga', 'limão', 'arroz', 'coentros']::text[], array['light']::text[], '[]'::jsonb, 'Branco de Bucelas (Arinto)', 14, true, false, 10),
  ('00000000-0000-4000-8000-0000000d1011', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca703', 'Bife à Casa do Mar', 'Novilho maturado 30 dias, molho de manteiga e alho, ovo estrelado e batata frita da casa.', 2400, 'https://images.unsplash.com/photo-1600891964092-4316c288032e?auto=format&fit=crop&w=1200&q=75', array['milk', 'eggs', 'sulphites']::text[], array['novilho maturado', 'manteiga', 'alho', 'ovo', 'batata', 'vinho branco']::text[], array['popular']::text[], '[{"id":"ponto","name":"Ponto da carne","min":1,"max":1,"choices":[{"id":"mal","name":"Mal passado","priceDeltaCents":0},{"id":"medio","name":"Médio","priceDeltaCents":0},{"id":"bem","name":"Bem passado","priceDeltaCents":0}]},{"id":"extra","name":"Acompanhamento extra","min":0,"max":2,"choices":[{"id":"batata-frita","name":"Batata frita da casa","priceDeltaCents":350},{"id":"salada","name":"Salada mista","priceDeltaCents":300},{"id":"arroz","name":"Arroz de tomate","priceDeltaCents":400}]}]'::jsonb, 'Tinto do Douro ou Alentejo', 16, true, false, 11),
  ('00000000-0000-4000-8000-0000000d1012', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca703', 'Secretos de porco preto', 'Porco preto alentejano na brasa, migas de espargos e laranja.', 1950, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1200&q=75', array['gluten']::text[], array['porco preto', 'pão alentejano', 'espargos', 'alho', 'laranja']::text[], array['signature']::text[], '[]'::jsonb, 'Tinto do Alentejo', 16, true, false, 12),
  ('00000000-0000-4000-8000-0000000d1013', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca704', 'Arroz de tomate e cogumelos', 'Arroz malandrinho de tomate maduro, cogumelos salteados, ovo a baixa temperatura e poejo.', 1500, 'https://images.unsplash.com/photo-1476124369491-e7addf5db371?auto=format&fit=crop&w=1200&q=75', array['eggs', 'celery']::text[], array['arroz carolino', 'tomate', 'cogumelos', 'ovo', 'poejo', 'cebola']::text[], array['vegetarian', 'gluten_free']::text[], '[]'::jsonb, 'Rosé ou branco leve', 22, true, false, 13),
  ('00000000-0000-4000-8000-0000000d1014', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca704', 'Salada de grão, abóbora e romã', 'Grão-de-bico, abóbora assada, rúcula, romã, sementes tostadas e vinagrete de citrinos.', 1300, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=1200&q=75', array['sesame', 'mustard']::text[], array['grão-de-bico', 'abóbora', 'rúcula', 'romã', 'sésamo', 'sementes de abóbora', 'laranja']::text[], array['vegan', 'light', 'gluten_free']::text[], '[]'::jsonb, 'Vinho Verde', 8, true, false, 14),
  ('00000000-0000-4000-8000-0000000d1015', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca705', 'Pastel de nata', 'Massa folhada estaladiça e creme de ovo, feito todas as manhãs. Canela e açúcar em pó à parte.', 220, 'https://images.unsplash.com/photo-1587241321921-91a834d6d191?auto=format&fit=crop&w=1200&q=75', array['gluten', 'eggs', 'milk']::text[], array['massa folhada', 'ovo', 'leite', 'açúcar', 'canela', 'limão']::text[], array['popular', 'vegetarian']::text[], '[]'::jsonb, 'Café ou Porto Tawny', 2, true, false, 15),
  ('00000000-0000-4000-8000-0000000d1016', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca705', 'Pudim Abade de Priscos', 'O pudim conventual de Braga: gemas, caramelo, vinho do Porto e um segredo de toucinho.', 650, 'https://images.unsplash.com/photo-1528975604071-b4dc52a2d18c?auto=format&fit=crop&w=1200&q=75', array['eggs', 'sulphites']::text[], array['gemas', 'açúcar', 'vinho do Porto', 'toucinho', 'limão', 'canela']::text[], array['signature', 'gluten_free']::text[], '[]'::jsonb, 'Porto Tawny 10 anos', 2, true, false, 16),
  ('00000000-0000-4000-8000-0000000d1017', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca705', 'Mousse de chocolate e flor de sal', 'Chocolate negro 70%, azeite e flor de sal de Castro Marim.', 600, 'https://images.unsplash.com/photo-1541783245831-57d6fb0926d3?auto=format&fit=crop&w=1200&q=75', array['eggs', 'milk']::text[], array['chocolate negro 70%', 'ovo', 'natas', 'azeite', 'flor de sal']::text[], array['vegetarian', 'gluten_free']::text[], '[]'::jsonb, 'Porto Ruby ou Moscatel de Setúbal', 2, true, false, 17),
  ('00000000-0000-4000-8000-0000000d1018', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca706', 'Soalheiro Alvarinho', 'Vinho Verde, Monção e Melgaço. Fresco, mineral, citrino. Feito para o marisco.', 650, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=1200&q=75', array['sulphites']::text[], array['uva Alvarinho']::text[], array['popular', 'vegan']::text[], '[{"id":"formato","name":"Formato","min":1,"max":1,"choices":[{"id":"copo","name":"Copo (15 cl)","priceDeltaCents":0},{"id":"garrafa","name":"Garrafa (75 cl)","priceDeltaCents":2150}]}]'::jsonb, null, 1, true, false, 18),
  ('00000000-0000-4000-8000-0000000d1019', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca706', 'Quinta do Crasto Tinto', 'Douro. Fruta vermelha, taninos suaves e final longo. Para carnes e pratos de tacho.', 700, 'https://images.unsplash.com/photo-1553361371-9b22f78e8b1d?auto=format&fit=crop&w=1200&q=75', array['sulphites']::text[], array['Touriga Nacional', 'Touriga Franca', 'Tinta Roriz']::text[], array['vegan']::text[], '[{"id":"formato","name":"Formato","min":1,"max":1,"choices":[{"id":"copo","name":"Copo (15 cl)","priceDeltaCents":0},{"id":"garrafa","name":"Garrafa (75 cl)","priceDeltaCents":2500}]}]'::jsonb, null, 1, true, false, 19),
  ('00000000-0000-4000-8000-0000000d1020', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca706', 'Limonada de hortelã', 'Limão espremido na hora, hortelã fresca e água com gás.', 400, 'https://images.unsplash.com/photo-1523371054106-bbf80586c38c?auto=format&fit=crop&w=1200&q=75', array[]::text[], array['limão', 'hortelã', 'água com gás', 'açúcar de cana']::text[], array['vegan', 'light']::text[], '[]'::jsonb, null, 3, true, false, 20),
  ('00000000-0000-4000-8000-0000000d1021', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca706', 'Água das Pedras', 'Água mineral gasocarbónica natural, 25 cl.', 250, null, array[]::text[], array['água mineral natural']::text[], array['vegan']::text[], '[]'::jsonb, null, 1, true, false, 21),
  ('00000000-0000-4000-8000-0000000d1022', '00000000-0000-4000-8000-00000000c0de', '00000000-0000-4000-8000-0000000ca706', 'Café', 'Lote da casa, torra média. Pergunte pelo pingado ou pelo galão.', 120, null, array[]::text[], array['café']::text[], array['vegan']::text[], '[]'::jsonb, null, 1, true, false, 22)
